 async function saveBadge(){await act(async()=>{const r=await chooseBadge(badge);if(r.error)throw r.error;staff.badge_number=badge.trim();return r})}
 async function loadComplaints(status:'active'|'closed'){const {data,error:e}=await supabase.from('complaints').select('*, opened_by:staff!complaints_created_by_fkey(display_name,badge_number)').eq('status',status).order(status==='active'?'updated_at':'closed_at',{ascending:false});if(e)setError(e.message);else setComplaints(data||[])}
 async function createComplaint(){setBusy(true);setError('');const initial={witnesses:[{}]};const {data,error:e}=await supabase.from('complaints').insert({created_by:staff.id,details:initial}).select('*').single();setBusy(false);if(e){setError(e.message);return}setSelectedComplaint(data);setComplaintDraft(initial);setComplaintView('new')}
