 const bridgeBase='https://pvahrnrtivzbkipborcd.supabase.co/functions/v1/lspd-bridge'
 const emsCategory:Record<string,string>={vet_followup:'veterinary_followup',medical_visit:'periodic_medical_visit',cas:'cas',cappa:'cappa',work_stop:'work_stoppage',sick_leave:'sick_leave',billing:'billing',criminal_record:'criminal_record_request'}
 async function bridgeFetch(path:string,init?:RequestInit){const {data:{session}}=await supabase.auth.getSession();if(!session)throw new Error('Session expirée.');const r=await fetch(bridgeBase+path,{...init,headers:{...(init?.headers||{}),Authorization:'Bearer '+session.access_token}});const data=await r.json();if(!r.ok)throw new Error(data.error||'Erreur bridge EMS/LSPD');return data}
 async function loadEmsUnread(){try{const data=await bridgeFetch('?action=unread');setEmsUnread(data.counts||{})}catch{}}
 async function markEmsRead(view:string){const channel=emsCategory[view]||view;try{await bridgeFetch('?action=mark-read&channel='+encodeURIComponent(channel),{method:'POST'});await loadEmsUnread()}catch{}}
 async function loadEmsBridge(silent=false){if(emsView==='home')return;if(!silent){setBridgeLoading(true);setError('')}try{const data=emsView==='direction'?await bridgeFetch('?action=direction'):await bridgeFetch('?action=transfers&category='+encodeURIComponent(emsCategory[emsView]||''));const next=data.items||[];setBridgeItems(prev=>JSON.stringify(prev)===JSON.stringify(next)?prev:next)}catch(e:any){if(!silent)setError(e.message)}finally{if(!silent)setBridgeLoading(false)}}
 async function sendCriminalResponse(parentId:string){const files=criminalFiles[parentId]||[];if(!files.length)return setError('Ajoute le document du casier judiciaire vierge.');setBusy(true);setError('');try{const form=new FormData();form.append('parent_transfer_id',parentId);form.append('result',(criminalInfo[parentId]?.result||'').trim());form.append('notes',(criminalInfo[parentId]?.notes||'').trim());files.forEach(x=>form.append('files',x));await bridgeFetch('?action=criminal-response',{method:'POST',body:form});setCriminalFiles(p=>({...p,[parentId]:[]}));setCriminalInfo(p=>({...p,[parentId]:{result:'',notes:''}}));await loadEmsBridge()}catch(e:any){setError(e.message)}finally{setBusy(false)}}
 async function sendDirectionMessage(){if(!directionBody.trim()&&!directionFiles.length)return;setBusy(true);setError('');try{const form=new FormData();form.append('body',directionBody.trim());directionFiles.forEach(x=>form.append('files',x));await bridgeFetch('?action=direction-send',{method:'POST',body:form});setDirectionBody('');setDirectionFiles([]);await loadEmsBridge()}catch(e:any){setError(e.message)}finally{setBusy(false)}}
