 async function createK9Unit(){if(!newK9.handler_name.trim()||!newK9.badge_number.trim()||!newK9.dog_name.trim()||!newK9.dog_age||!newK9.dog_sex.trim()||!newK9.dog_breed.trim()||!newK9.training_date)return setError('Tous les champs de l’unité cynophile sont obligatoires.');setBusy(true);setError('');const {data,error:e}=await supabase.from('k9_units').insert({...newK9,handler_name:newK9.handler_name.trim(),badge_number:newK9.badge_number.trim(),dog_name:newK9.dog_name.trim(),dog_age:Number(newK9.dog_age),dog_sex:newK9.dog_sex.trim(),dog_breed:newK9.dog_breed.trim(),created_by:staff.id,sort_order:k9Units.length}).select('*').single();setBusy(false);if(e){setError(e.message);return}setK9Units(prev=>[...prev,data]);setNewK9({handler_name:'',badge_number:'',dog_name:'',dog_age:'',dog_sex:'',dog_breed:'',training_date:''})}
 async function moveK9Unit(sourceId:string,targetId:string){if(!sourceId||!targetId||sourceId===targetId)return;const from=k9Units.findIndex(x=>x.id===sourceId),to=k9Units.findIndex(x=>x.id===targetId);if(from<0||to<0)return;const next=[...k9Units],[moved]=next.splice(from,1);next.splice(to,0,moved);setK9Units(next);setDraggedK9Unit(null);const results=await Promise.all(next.map((x,i)=>supabase.from('k9_units').update({sort_order:i}).eq('id',x.id)));const failed=results.find(x=>x.error);if(failed?.error){setError(failed.error.message);void loadK9Units()}}
