 async function deleteDoaProfile(profile:any){if(!doaCanCreate)return;if(!confirm('Supprimer définitivement le carnet DOA de '+profile.agent_name+' (matricule '+profile.badge_number+'), ainsi que toutes ses tuiles, posts et photos ?'))return;setBusy(true);setError('');const {data:tiles,error:te}=await supabase.from('doa_tiles').select('id').eq('owner_badge',profile.badge_number);if(te){setBusy(false);setError(te.message);return}const ids=(tiles||[]).map((t:any)=>t.id);if(ids.length){const {data:imgs,error:ie}=await supabase.from('doa_tile_images').select('image_path').in('tile_id',ids);if(ie){setBusy(false);setError(ie.message);return}if(imgs?.length){const {error:se}=await supabase.storage.from('doa-media').remove(imgs.map((x:any)=>x.image_path));if(se){setBusy(false);setError(se.message);return}}const {error:de}=await supabase.from('doa_tiles').delete().in('id',ids);if(de){setBusy(false);setError(de.message);return}}const {error:e}=await supabase.from('doa_profiles').delete().eq('id',profile.id);setBusy(false);if(e){setError(e.message);return}setDoaProfiles(prev=>prev.filter(x=>x.id!==profile.id));if(doaProfile?.badge===profile.badge_number){setDoaProfile(null);setSelectedDoaTile(null);setDoaTiles([]);setDoaPosts([]);setDoaTileImages([])}}
