 const hspTilesRef=useRef<any[]>([])
 useEffect(()=>{hspTilesRef.current=hspTiles},[hspTiles])
 async function moveHspTile(sourceId:string,targetId:string){
  if(!sourceId||!targetId||sourceId===targetId)return
  const current=hspTilesRef.current
  const from=current.findIndex(x=>x.id===sourceId),to=current.findIndex(x=>x.id===targetId)
  if(from<0||to<0)return
  const next=[...current],[moved]=next.splice(from,1)
  next.splice(to,0,moved)
  hspTilesRef.current=next
  setHspTiles(next)
  setDraggedHspTile(null)
  const results=await Promise.all(next.map((x,i)=>supabase.from('hsp_tiles').update({sort_order:i}).eq('id',x.id)))
  const failed=results.find(x=>x.error)
  if(failed?.error){setError(failed.error.message);if(selectedHsp)void openHspProfile(selectedHsp)}
 }

