  const identity=['IDENTIFICATION DU RAPPORT',[['Intitulé',operation.title||type],['Rapport ouvert par',operation.opened_by?.display_name?operation.opened_by.display_name+(operation.opened_by.badge_number?' · Matricule '+operation.opened_by.badge_number:''):'Agent inconnu'],['Créé le',new Date(operation.created_at).toLocaleString('fr-FR')],['Clôturé le',operation.closed_at?new Date(operation.closed_at).toLocaleString('fr-FR'):'—']]];
