   sections.push(['INFORMATIONS DE L’OPÉRATION',[['Type d’opération effectuée',d.operation_kind],['Lieu',d.location],['Date',d.date],['Heure de début',d.start_time],['Heure de fin',d.end_time]]],['AGENTS ENGAGÉS',[['Noms / matricules / unités / rôles',d.officers]]],['INDIVIDUS ARRÊTÉS',[['Identités / informations',d.arrested]]],['ÉLÉMENTS SAISIS / PREUVES RÉCUPÉRÉES',[['Éléments saisis',d.seized_items]]],['USAGE DE LA FORCE',[['Utilisation de la force',d.force_used],['Arme à feu',d.firearm_used],['Taser',d.taser_used]]],['DESCRIPTION DE L’OPÉRATION',[['Déroulement complet',d.description]]]);
